// Domain layer — generated by line-matcher. Do not add logic that belongs to another layer.
// Pure functions only: no network, storage or DOM.

export function asText(v) {
  return String(v);
}

// Rows for the "orgs-items" list.
export function toOrgsItemRows(items) {
  return items.map((item) => ({
    id: item.id,
    name: asText(item.name),
    sku: asText(item.sku),
    qty: asText(item.qty),
  }));
}

// "itemCount" = count. Design showed "3".
export function itemCount(items) {
  return asText(items.length);
}

// "qtyTotal" = sum(qty). Design showed "69".
export function qtyTotal(items) {
  return asText(items.reduce((s, x) => s + Number(x.qty), 0));
}

export function findOrgsItem(items, id) {
  return items.find((item) => item.id === id) ?? null;
}

// Form text -> the types the API expects (taken from the example request body).
export function toOrgsItemInput(values) {
  return {
    name: String(values.name ?? "").trim(),
    sku: String(values.sku ?? "").trim(),
    qty: Number(values.qty),
  };
}

// Raw values to prefill the form when an item is selected.
export function toFormValues(item) {
  if (!item) return {};
  return {
    name: item.name,
    sku: item.sku,
    qty: item.qty,
  };
}
